using Cosmos.API.Security;using Cosmos.Application.Abstractions.Services;using Cosmos.Application.PurchaseExpense;using Cosmos.Domain.Security;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace Cosmos.API.Controllers;
[Authorize,Tags("SupplierPaymentsController"),ApiExplorerSettings(GroupName="Purchase & Expense"),Route("api/supplier-payments")]
public sealed class SupplierPaymentsController(IPurchaseExpenseService s):ApiControllerBase { [HttpGet,RequirePermission("PurchaseExpense.PaymentOut",PermissionAction.View)]public async Task<IActionResult> List([FromQuery]SupplierPaymentListQuery q,CancellationToken ct)=>FromResponse(await s.GetSupplierPaymentsAsync(q,ct));[HttpGet("{id:long}"),RequirePermission("PurchaseExpense.PaymentOut",PermissionAction.View)]public async Task<IActionResult> Get(long id,CancellationToken ct)=>FromResponse(await s.GetSupplierPaymentAsync(id,ct));[HttpPost,RequirePermission("PurchaseExpense.PaymentOut",PermissionAction.Create)]public async Task<IActionResult>Create(CreateSupplierPaymentRequest r,CancellationToken ct)=>FromResponse(await s.CreateSupplierPaymentAsync(r,ct),201);[HttpPut("{id:long}"),RequirePermission("PurchaseExpense.PaymentOut",PermissionAction.Edit)]public async Task<IActionResult>Update(long id,UpdateSupplierPaymentRequest r,CancellationToken ct)=>FromResponse(await s.UpdateSupplierPaymentAsync(id,r,ct));[HttpDelete("{id:long}"),RequirePermission("PurchaseExpense.PaymentOut",PermissionAction.Delete)]public async Task<IActionResult>Delete(long id,CancellationToken ct)=>FromResponse(await s.DeleteSupplierPaymentAsync(id,ct)); }
